In:  msg.payload = { kommun: {kod,namn,lan_kod,lan_namn}, ar, valtyp }
Ut:  msg.payload = { meta, geojson: FeatureCollection, uppsamlingsdistrikt }

Hämtar valdistriktens geometri + resultat för valt år från val.se, hämtar samma sak för jämförelsevalet (ar - 4), normaliserar och slår ihop dem. Kastar ett Error om varken geometri eller aktuellt resultat kunde hämtas (fångas av en Catch-nod i den anropande fliken).

func:
// ============================================================================
// Subflow "HamtaValdata" - enda funktionsnoden.
// In:  msg.payload = { kommun: {kod,namn,lan_kod,lan_namn}, ar, valtyp }
// Ut:  msg.payload = { meta, geojson: FeatureCollection, uppsamlingsdistrikt }
//
// OBS: fältnamnen som letas upp med H.pickField() nedan är BÄSTA GISSNING
// utifrån val.se:s dokumentation (svenska namn som "distriktskod", "parti",
// "röster" osv). De är INTE verifierade mot en riktig fil (val.se är inte
// nåbart från miljön där detta skrevs). När du kör detta första gången mot
// riktig data kommer eventuella felmeddelanden att lista de FAKTISKA
// fältnamnen i JSON-svaret från val.se - lägg då till dem först i
// kandidatlistan för respektive fält nedan.
// ============================================================================
const H = global.get("valHelpers");
const cfg = global.get("valConfig");

const { kommun, ar, valtyp } = msg.payload;
const lanKod = kommun.lan_kod;
const isLive = cfg.liveYears.indexOf(ar) !== -1;
const ttl = isLive ? cfg.cacheTtlLiveMs : cfg.cacheTtlFinalMs;
const jamforAr = ar - cfg.jamforOffsetAr;
const varningar = [];

// ---------------------------------------------------------------------------
// 1. Hämta geometrifil (valdistriktens utbredning) för länet.
// ---------------------------------------------------------------------------
let geoFeatures = [];
try {
    const geoUrl = H.fillUrlTemplate(cfg.urls.geo, { ar, lan_kod: lanKod });
    const geoJson = await H.fetchJson(geoUrl, `geo_${ar}_${lanKod}`, ttl);
    const allFeatures = geoJson.features || geoJson.Features || [];
    geoFeatures = allFeatures.filter((f) => {
        const kkod = H.pickField(f.properties, ["kommun_kod", "kommunKod", "kommunkod", "KOMMUN"], {
            default: null
        });
        return kkod === kommun.kod || String(kkod).padStart(4, "0") === kommun.kod;
    });
} catch (e) {
    varningar.push("Kunde inte hämta/tolka geometrifil: " + e.message);
}

// ---------------------------------------------------------------------------
// 2. Normaliserar en resultatfil (JSON från val.se) till en Map<distriktskod, post>
// ---------------------------------------------------------------------------
function extraheraDistriktLista(raw) {
    if (Array.isArray(raw)) return raw;
    const kand = ["distrikt", "omraden", "resultat", "data", "records", "valdistrikt"];
    for (const k of kand) {
        if (Array.isArray(raw[k])) return raw[k];
    }
    throw new Error(
        "Hittade ingen lista med distrikt i svaret. Toppnivåfält: [" + Object.keys(raw).join(", ") + "]"
    );
}

function normaliseraRoster(rawParti) {
    return rawParti.map((p) => ({
        parti: String(
            H.pickField(p, ["partiKod", "parti", "beteckning", "kod", "party"], { required: true, label: "partikod" })
        ).toUpperCase(),
        röster: Number(H.pickField(p, ["röster", "rostetal", "antalRoster", "votes", "antal"], { default: 0 })),
        andel: Number(H.pickField(p, ["andel", "procent", "share", "andelProcent"], { default: 0 })),
        mandat: H.pickField(p, ["mandat", "antalMandat", "seats"], { default: null })
    }));
}

async function hamtaOchNormaliseraResultat(forAr) {
    const url = H.fillUrlTemplate(cfg.urls.resultat, { ar: forAr, lan_kod: lanKod, valtyp });
    const raw = await H.fetchJson(url, `resultat_${forAr}_${valtyp}_${lanKod}`, ttl);
    const lista = extraheraDistriktLista(raw);

    const byKod = new Map();
    for (const rec of lista) {
        const kkod = String(
            H.pickField(rec, ["kommunkod", "kommun_kod", "kommunKod"], { default: "" })
        ).padStart(4, "0");
        const kod = String(
            H.pickField(rec, ["distriktskod", "distrikt_kod", "omradeskod", "kod", "id"], {
                required: true,
                label: "distriktskod"
            })
        );
        // Om posten saknar egen kommunkod, härled den ur distriktskodens 4 första tecken
        // (svensk konvention: distriktskod = 4 siffror kommun + löpnummer).
        const effektivKkod = kkod && kkod !== "0000" ? kkod : kod.slice(0, 4);
        if (effektivKkod !== kommun.kod) continue;

        const namn = String(H.pickField(rec, ["distriktnamn", "namn", "name"], { default: kod }));
        const typRaw = H.pickField(rec, ["typ", "distriktstyp"], { default: "" });
        const arUppsamling =
            /uppsamling/i.test(String(typRaw)) || /uppsamling/i.test(namn) ||
            H.pickField(rec, ["ar_uppsamlingsdistrikt", "uppsamlingsdistrikt"], { default: false }) === true;

        const rawRoster = H.pickField(rec, ["partier", "resultat", "partiResultat", "roster", "votes"], {
            required: true,
            label: "partiresultat för distrikt " + kod
        });
        const roster = normaliseraRoster(rawRoster);
        const valdeltagande = H.pickField(rec, ["valdeltagande", "rostdeltagande", "deltagande", "turnout"], {
            default: null
        });

        let ledandeParti = null;
        let bastAndel = -1;
        for (const p of roster) {
            if (p.andel > bastAndel) {
                bastAndel = p.andel;
                ledandeParti = p.parti;
            }
        }

        byKod.set(kod, {
            kod,
            namn,
            typ: arUppsamling ? "uppsamling" : "ordinarie",
            valdeltagande,
            roster,
            ledandeParti
        });
    }
    return byKod;
}

// ---------------------------------------------------------------------------
// 3. Hämta nuvarande och (om möjligt) föregående jämförelseval.
// ---------------------------------------------------------------------------
let currentByKod = new Map();
try {
    currentByKod = await hamtaOchNormaliseraResultat(ar);
} catch (e) {
    varningar.push("Kunde inte hämta/tolka resultatfil för " + ar + ": " + e.message);
}

let prevByKod = new Map();
let harJamforelse = true;
try {
    prevByKod = await hamtaOchNormaliseraResultat(jamforAr);
} catch (e) {
    harJamforelse = false;
    varningar.push("Kunde inte hämta jämförelseval " + jamforAr + ": " + e.message);
}

if (currentByKod.size === 0 && geoFeatures.length === 0) {
    // Inget att visa alls - eskalera till fel så anropande flöde kan svara 502.
    const err = new Error(varningar.join(" | ") || "Ingen data hittades.");
    throw err;
}

// ---------------------------------------------------------------------------
// 4. Bygg jämförelse per distrikt (nuvarande vs föregående val).
// ---------------------------------------------------------------------------
function byggJamforandeDistrikt(kod, curr) {
    const prev = prevByKod.get(kod);
    const jamforbar = harJamforelse && !!prev;

    const roster = curr.roster.map((p) => {
        const prevParti = prev ? prev.roster.find((pp) => pp.parti === p.parti) : null;
        return {
            parti: p.parti,
            röster: p.röster,
            andel: p.andel,
            mandat: p.mandat,
            andel_forra: prevParti ? prevParti.andel : null,
            forandring: prevParti ? Number((p.andel - prevParti.andel).toFixed(2)) : null
        };
    });

    return {
        kod: curr.kod,
        namn: curr.namn,
        typ: curr.typ,
        valdeltagande: curr.valdeltagande,
        valdeltagande_forra: prev ? prev.valdeltagande : null,
        roster,
        ledandeParti: curr.ledandeParti,
        ledandeParti_forra: prev ? prev.ledandeParti : null,
        partibyte: jamforbar ? prev.ledandeParti !== curr.ledandeParti : false,
        jamforbar
    };
}

const geoByKod = new Map();
for (const f of geoFeatures) {
    const kod = String(
        H.pickField(f.properties, ["distriktskod", "distrikt_kod", "omradeskod", "kod", "id"], {
            required: true,
            label: "distriktskod (geometri)"
        })
    );
    geoByKod.set(kod, f);
}

const features = [];
const uppsamlingsdistrikt = [];

for (const [kod, curr] of currentByKod.entries()) {
    const properties = byggJamforandeDistrikt(kod, curr);
    const geoFeature = geoByKod.get(kod);
    if (geoFeature && curr.typ !== "uppsamling") {
        features.push({
            type: "Feature",
            geometry: geoFeature.geometry,
            properties
        });
    } else {
        uppsamlingsdistrikt.push(properties);
    }
}

// ---------------------------------------------------------------------------
// 5. Klart - bygg svaret.
// ---------------------------------------------------------------------------
msg.payload = {
    meta: {
        kommun,
        ar,
        valtyp,
        jamforAr: harJamforelse ? jamforAr : null,
        ar_live: isLive,
        senast_uppdaterad: new Date().toISOString(),
        kalla: "val.se",
        varningar
    },
    geojson: {
        type: "FeatureCollection",
        features
    },
    uppsamlingsdistrikt
};

return msg;

// GET /val/api/kommuner -> lista över Sveriges 290 kommuner (kod, namn, län).
const H = global.get("valHelpers");
try {
    msg.payload = H.cachedReadJson("kommuner.json");
    msg.statusCode = 200;
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: "Kunde inte läsa kommuner.json", detalj: e.message };
}
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/valtyper -> riksdag / region / kommun
const H = global.get("valHelpers");
try {
    msg.payload = H.cachedReadJson("valtyper.json");
    msg.statusCode = 200;
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: "Kunde inte läsa valtyper.json", detalj: e.message };
}
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/partier -> färgsättning per parti (redigera gärna hex-koderna)
const H = global.get("valHelpers");
try {
    msg.payload = H.cachedReadJson("party-styles.json");
    msg.statusCode = 200;
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: "Kunde inte läsa party-styles.json", detalj: e.message };
}
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/ar -> valbara år, med status "live" (pollas i realtid) eller
// "final" (slutgiltigt facit, hämtas en gång och cachas).
const cfg = global.get("valConfig");

const live = cfg.liveYears.map((ar) => ({ ar, status: "live", namn: ar + " (pågående)" }));
const final = cfg.finalYears.map((ar) => ({ ar, status: "final", namn: String(ar) }));

const alla = live.concat(final).sort((a, b) => b.ar - a.ar);

msg.payload = alla;
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/valdistrikt?kommun=1281&ar=2022&valtyp=riksdag
// Två utgångar: 0 = ogiltig fråga (går direkt till http response),
//               1 = giltig fråga (går vidare till subflowet HamtaValdata).
const H = global.get("valHelpers");
const q = msg.req.query || {};

const kommunKod = String(q.kommun || "").trim();
const ar = parseInt(q.ar, 10);
const valtyp = String(q.valtyp || "").trim();
const giltigaValtyper = ["riksdag", "region", "kommun"];

let kommuner;
try {
    kommuner = H.cachedReadJson("kommuner.json");
} catch (e) {
    msg.statusCode = 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "Kunde inte läsa kommunlistan", detalj: e.message };
    return [msg, null];
}

const kommunInfo = kommuner.find((k) => k.kod === kommunKod);
const fel = [];
if (!kommunInfo) fel.push("okänd kommunkod: '" + kommunKod + "'");
if (!Number.isInteger(ar) || ar < 2002 || ar > 2100) fel.push("ogiltigt år: '" + q.ar + "'");
if (giltigaValtyper.indexOf(valtyp) === -1) {
    fel.push("ogiltig valtyp (måste vara riksdag/region/kommun): '" + valtyp + "'");
}

if (fel.length) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "Ogiltig förfrågan", detaljer: fel };
    return [msg, null];
}

msg.payload = { kommun: kommunInfo, ar, valtyp };
return [null, msg];

// Efter lyckat anrop till subflowet HamtaValdata: paketera som HTTP 200-svar.
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// Fångar fel som kastas i subflowet HamtaValdata (t.ex. att val.se inte
// svarar, eller att ett fältnamn i normaliseringen inte hittas) och gör om
// dem till ett tydligt JSON-felsvar istället för att flödet kraschar tyst.
const err = msg.error || {};
node.warn("Fel vid hämtning av valdata: " + (err.message || JSON.stringify(err)));

msg.statusCode = 502;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
    error: "Kunde inte hämta/tolka valresultat",
    detalj: err.message || String(err)
};
return msg;

// Statisk filserver för /val/* (Leaflet-kartan, JS, CSS).
// Kopplad från: http in "GET /val" och "GET /val/*"  ->  denna nod -> http response
// fs/path laddas via denna nods "Setup"-flik (redan ifyllt i flows-val.json),
// inte via require()/global.get(). cfg kommer från initConfig-noden.
const cfg = global.get("valConfig");
if (typeof fs === "undefined" || typeof path === "undefined" || !cfg) {
    msg.statusCode = 500;
    msg.payload = "Servern är inte klar (fs/path/valConfig saknas - se node-red/README.md).";
    return msg;
}

const MIME = {
    ".html": "text/html; charset=utf-8",
    ".js": "application/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".ico": "image/x-icon",
    ".webmanifest": "application/manifest+json"
};

let reqPath = "";
if (msg.req.params && msg.req.params[0] !== undefined) {
    reqPath = msg.req.params[0];
} else if (msg.req.path) {
    reqPath = msg.req.path.replace(/^\/val\/?/, "");
}
if (reqPath === "" || reqPath.endsWith("/")) {
    reqPath += "index.html";
}

// Skydda mot path traversal ("../../etc/passwd" etc).
const resolved = path.resolve(cfg.webRoot, reqPath);
if (!resolved.startsWith(path.resolve(cfg.webRoot))) {
    msg.statusCode = 403;
    msg.payload = "Förbjuden sökväg";
    return msg;
}

try {
    const data = fs.readFileSync(resolved);
    const ext = path.extname(resolved).toLowerCase();
    msg.headers = { "Content-Type": MIME[ext] || "application/octet-stream" };
    msg.statusCode = 200;
    msg.payload = data;
} catch (e) {
    msg.statusCode = 404;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload = "Hittar inte filen: " + reqPath;
}
return msg;

// ============================================================================
// INIT: körs en gång vid Deploy (triggas av injektionsnoden "Starta vid deploy")
// Sätter global konfiguration + delade hjälpfunktioner som resten av flödet
// (API-noderna, HamtaValdata-subflowet, polling-flödet) läser via global context.
// ============================================================================

// ---------------------------------------------------------------------------
// !!! ÄNDRA DESSA SÖKVÄGAR så de stämmer med var du lade filerna på servern !!!
// DATA_DIR   = mappen "node-red/data" från repot (kommuner.json, valtyper.json,
//              party-styles.json). Behöver bara vara LÄSBAR.
// WEB_ROOT   = mappen "web/val" från repot (index.html, karta.html, css, js).
//              Behöver bara vara läsbar.
// CACHE_DIR  = en SKRIVBAR katalog för nedladdad val.se-data (skapas
//              automatiskt om den saknas). Måste vara skrivbar för den
//              Node-RED-processen faktiskt kör som - i vissa miljöer (t.ex.
//              containrar) är /opt inte skrivbart och /tmp är enda alternativet;
//              byt då CACHE_DIR nedan. Ligger cachen under /tmp kan den
//              försvinna vid omstart - det är ofarligt, den byggs bara upp
//              på nytt vid nästa hämtning.
// ---------------------------------------------------------------------------
const DATA_DIR = "/opt/nodered/val/data";
const WEB_ROOT = "/opt/nodered/val/web/val";
const CACHE_DIR = "/tmp/val-cache";

// OBS: fs och path kommer INTE från require() eller global.get() - de laddas
// via denna nods "Setup"-flik (modulnamn "fs" importerad som "fs", samma för
// "path"), vilket redan är förifyllt i flows-val.json (nodens "libs"-fält).
// Det enda du behöver göra i settings.js är att sätta
// `functionExternalModules: true` en gång (se node-red/README.md) - det är
// Node-RED:s inbyggda, avsedda mekanism för just detta och kräver ingen
// egen require()-kod i settings.js.
if (typeof fs === "undefined" || typeof path === "undefined") {
    throw new Error(
        "Modulerna fs/path är inte laddade. Kontrollera att " +
        "`functionExternalModules: true` är satt i din Node-RED settings.js " +
        "(och att processen startats om), samt att denna nods Setup-flik " +
        "listar fs och path. Se node-red/README.md."
    );
}

// Skapa cache-katalogen om den saknas.
try {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
} catch (e) {
    node.warn("Kunde inte skapa cache-katalogen " + CACHE_DIR + ": " + e.message);
}

// ---------------------------------------------------------------------------
// URL-mallar för val.se:s rådata. {ar} / {lan_kod} / {kommun_kod} / {valtyp}
// byts ut av valHelpers.fillUrlTemplate().
//
// !!! DESSA ÄR PLACEHOLDERS OCH MÅSTE VERIFIERAS MOT DEN RIKTIGA WEBBPLATSEN !!!
// val.se är blockerad från utvecklingsmiljön den här koden skrevs i, så
// exakta filnamn/sökvägar har inte kunnat verifieras automatiskt.
//
// Så här hittar du de riktiga URL:erna (tar ~5 minuter):
//   1. Gå till https://www.val.se/valresultat-och-statistik/statistik-och-data
//      och öppna sidan för "Rådata" (2002-2022 för historik, "Rådata val 2026"
//      för valnatten). Ladda ner/öppna en fil för ett valår + valtyp + län och
//      notera den riktiga URL:en och filens fältnamn.
//   2. Alternativt: öppna https://resultat.val.se (valresultatsajten) i
//      webbläsaren, öppna Nätverksfliken (F12 -> Network) och titta på vilka
//      JSON-anrop sidan gör när du väljer ett valdistrikt/kommun. Det är
//      exakt samma data vi vill hämta här.
//   3. Uppdatera `urls.geo` och `urls.resultat` nedan, samt fältnamnen i
//      valHelpers.pickField-anropen i funktionsnoden "Hämta, normalisera och
//      jämför" (i subflowet HamtaValdata) om de skiljer sig.
// ---------------------------------------------------------------------------
const urls = {
    // Geometrifiler (valdistriktens utbredning), en fil per län, SWEREF99 TM.
    geo: "https://www.val.se/PLACEHOLDER-VERIFIERA/geodata/{ar}/{lan_kod}.json",
    // Resultatfiler (röster/mandat/valdeltagande per distrikt), en fil per
    // län och valtyp.
    resultat: "https://www.val.se/PLACEHOLDER-VERIFIERA/radata/{ar}/{valtyp}/{lan_kod}.json"
};

// Vilka valår som är "levande" (pollas kontinuerligt via WS under valkvällen)
// resp. "slutgiltiga" (hämtas en gång och cachas permanent).
const liveYears = [2026];
const finalYears = [2022, 2018, 2014, 2010];

global.set("valConfig", {
    dataDir: DATA_DIR,
    webRoot: WEB_ROOT,
    cacheDir: CACHE_DIR,
    urls: urls,
    liveYears: liveYears,
    finalYears: finalYears,
    // Hur många år bakåt jämförelsen ska gå (val hålls vart 4:e år i Sverige).
    jamforOffsetAr: 4,
    // Hur ofta (ms) pollningsflödet kollar om det finns nya siffror för
    // levande prenumerationer.
    pollIntervalMs: 30000,
    // Hur länge (ms) en hämtad länsfil (geo/resultat) får cachas innan den
    // hämtas på nytt. Slutgiltiga år (2018, 2022, ...) cachas i praktiken
    // för alltid (30 dagar), levande år (2026) cachas bara en kort stund.
    cacheTtlLiveMs: 20000,
    cacheTtlFinalMs: 1000 * 60 * 60 * 24 * 30
});

// ---------------------------------------------------------------------------
// Delade hjälpfunktioner, tillgängliga i alla andra function-noder via:
//   const H = global.get("valHelpers");
// ---------------------------------------------------------------------------
const memoryJsonCache = new Map();

function cachedReadJson(fileName) {
    if (memoryJsonCache.has(fileName)) return memoryJsonCache.get(fileName);
    const full = path.join(DATA_DIR, fileName);
    const data = JSON.parse(fs.readFileSync(full, "utf8"));
    memoryJsonCache.set(fileName, data);
    return data;
}

function fillUrlTemplate(tpl, vars) {
    return tpl.replace(/\{(\w+)\}/g, (m, key) => {
        if (!(key in vars) || vars[key] === undefined || vars[key] === null) {
            throw new Error("Saknar värde för platshållare {" + key + "} i URL-mall: " + tpl);
        }
        return encodeURIComponent(vars[key]);
    });
}

function kommunLanKod(kommunKod) {
    return String(kommunKod).padStart(4, "0").slice(0, 2);
}

// Hämtar JSON över HTTP(S) med enkel filcache på disk. `cacheKey` blir
// filnamnet i cache-katalogen. `ttlMs` = hur länge cachen får användas.
async function fetchJson(url, cacheKey, ttlMs) {
    const cacheFile = path.join(CACHE_DIR, cacheKey.replace(/[^a-zA-Z0-9_.-]/g, "_") + ".json");
    try {
        const stat = fs.statSync(cacheFile);
        if (Date.now() - stat.mtimeMs < ttlMs) {
            return JSON.parse(fs.readFileSync(cacheFile, "utf8"));
        }
    } catch (e) {
        // ingen cache ännu, fortsätt till hämtning
    }

    if (typeof fetch !== "function") {
        throw new Error(
            "global fetch() saknas i denna Node-RED/Node.js-version. " +
            "Kör Node.js 18+ , eller byt ut fetchJson() mot http request-noder."
        );
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);
    let res;
    try {
        res = await fetch(url, { signal: controller.signal, headers: { "User-Agent": "val-karta-nodered/1.0" } });
    } catch (e) {
        throw new Error("Kunde inte nå " + url + ": " + e.message);
    } finally {
        clearTimeout(timeout);
    }
    if (!res.ok) {
        throw new Error("HTTP " + res.status + " från " + url);
    }
    const json = await res.json();
    try {
        fs.writeFileSync(cacheFile, JSON.stringify(json));
    } catch (e) {
        node.warn("Kunde inte skriva cache " + cacheFile + ": " + e.message);
    }
    return json;
}

// Letar efter första matchande fältet i `obj` bland `candidates` (skiftlägesokänsligt).
// Kastar ett tydligt fel som listar de FAKTISKA nycklarna i objektet om inget
// hittas och `required` är sant — det gör det snabbt att lägga till rätt
// fältnamn när ni har verifierat den riktiga val.se-strukturen.
function pickField(obj, candidates, opts) {
    opts = opts || {};
    const keys = Object.keys(obj || {});
    const lowerMap = {};
    keys.forEach((k) => (lowerMap[k.toLowerCase()] = k));
    for (const c of candidates) {
        if (obj && Object.prototype.hasOwnProperty.call(obj, c)) return obj[c];
        const hit = lowerMap[c.toLowerCase()];
        if (hit !== undefined) return obj[hit];
    }
    if (opts.required) {
        throw new Error(
            "Hittade inget av fälten [" + candidates.join(", ") + "] (" + (opts.label || "okänt fält") +
            "). Faktiska fält i objektet: [" + keys.join(", ") + "]. " +
            "Lägg till rätt fältnamn i pickField-anropet i funktionsnoden."
        );
    }
    return opts.default;
}

global.set("valHelpers", {
    cachedReadJson,
    fillUrlTemplate,
    kommunLanKod,
    fetchJson,
    pickField
});

node.warn("val-karta: konfiguration och hjälpfunktioner initierade.");
return null;

// websocket in (/val/ws) -> denna nod. Hanterar prenumerationer.
// Klienten (web/val/js/karta.js) skickar:
//   {"type":"subscribe","kommun":"1281","ar":2022,"valtyp":"riksdag"}
// och skickar om samma meddelande var ~20:e sekund som "heartbeat" så att
// vi vet att fliken fortfarande är öppen (annars städas prenumerationen bort
// automatiskt av buildPollList efter 90 sekunders tystnad).
let data;
try {
    data = JSON.parse(msg.payload);
} catch (e) {
    node.warn("Ogiltigt WS-meddelande (inte JSON): " + msg.payload);
    return null;
}

const sessionId = msg._session && msg._session.id;
if (!sessionId) return null;

const subs = flow.get("wsSubs") || {};

if (data.type === "subscribe") {
    subs[sessionId] = {
        kommun: String(data.kommun),
        ar: parseInt(data.ar, 10),
        valtyp: String(data.valtyp),
        lastSeen: Date.now()
    };
    flow.set("wsSubs", subs);
} else if (data.type === "unsubscribe") {
    delete subs[sessionId];
    flow.set("wsSubs", subs);
}

node.status({ fill: "green", shape: "dot", text: Object.keys(subs).length + " prenumeranter" });
return null;

// Injiceras var `valConfig.pollIntervalMs` ms. Städar bort inaktiva
// WS-prenumerationer och bygger en lista med unika {kommun,ar,valtyp} som
// ska pollas mot val.se just nu (bara "levande" valår, se valConfig.liveYears).
// Ett utgående meddelande per kombination skickas vidare till subflowet
// HamtaValdata (kopplat direkt på denna nods enda utgång).
const cfg = global.get("valConfig");
const H = global.get("valHelpers");
const STALE_MS = 90000;
const now = Date.now();

const subs = flow.get("wsSubs") || {};
let ändrat = false;
for (const sid of Object.keys(subs)) {
    if (!subs[sid].lastSeen || now - subs[sid].lastSeen > STALE_MS) {
        delete subs[sid];
        ändrat = true;
    }
}
if (ändrat) flow.set("wsSubs", subs);

const unika = new Map();
for (const s of Object.values(subs)) {
    if (cfg.liveYears.indexOf(s.ar) === -1) continue; // slutgiltiga år pollas inte, bara skickas en gång via REST
    const key = s.kommun + "|" + s.ar + "|" + s.valtyp;
    if (!unika.has(key)) unika.set(key, { kommun: s.kommun, ar: s.ar, valtyp: s.valtyp });
}

node.status({ fill: "blue", shape: "dot", text: unika.size + " kombinationer pollas" });

if (unika.size === 0) return null;

let kommuner;
try {
    kommuner = H.cachedReadJson("kommuner.json");
} catch (e) {
    node.warn("buildPollList: kunde inte läsa kommuner.json: " + e.message);
    return null;
}

const meddelanden = [];
for (const combo of unika.values()) {
    const kommunInfo = kommuner.find((k) => k.kod === combo.kommun);
    if (!kommunInfo) continue;
    meddelanden.push({ payload: { kommun: kommunInfo, ar: combo.ar, valtyp: combo.valtyp } });
}

if (meddelanden.length === 0) return null;
return [meddelanden];

// Tar emot ett färskt resultat från subflowet HamtaValdata (en gång per
// {kommun,ar,valtyp}-kombination som pollas), jämför mot senast utskickade
// version och skickar bara ut det som faktiskt ändrats till de klienter som
// prenumererar på just den kombinationen. Kopplad till: websocket out (/val/ws).
const { meta, geojson, uppsamlingsdistrikt } = msg.payload;
const key = meta.kommun.kod + "|" + meta.ar + "|" + meta.valtyp;
const snapshotKey = "lastBroadcast_" + key;

const previous = global.get(snapshotKey) || {};
const nyaSnapshot = {};

function harAndrats(kod, properties) {
    const serialized = JSON.stringify(properties);
    nyaSnapshot[kod] = serialized;
    return previous[kod] !== serialized;
}

const distriktAndrade = [];
for (const f of geojson.features) {
    if (harAndrats(f.properties.kod, f.properties)) distriktAndrade.push(f.properties);
}
const uppsamlingAndrade = [];
for (const u of uppsamlingsdistrikt) {
    if (harAndrats(u.kod, u)) uppsamlingAndrade.push(u);
}

global.set(snapshotKey, nyaSnapshot);

const subs = flow.get("wsSubs") || {};
const targetSessions = Object.keys(subs).filter((sid) => {
    const s = subs[sid];
    return s.kommun === meta.kommun.kod && s.ar === meta.ar && s.valtyp === meta.valtyp;
});

if (targetSessions.length === 0) return null;

const harAndringar = distriktAndrade.length > 0 || uppsamlingAndrade.length > 0;
const payload = JSON.stringify({
    type: harAndringar ? "update" : "status",
    kommun: meta.kommun.kod,
    ar: meta.ar,
    valtyp: meta.valtyp,
    ar_live: meta.ar_live,
    senast_uppdaterad: meta.senast_uppdaterad,
    varningar: meta.varningar,
    distrikt: distriktAndrade,
    uppsamlingsdistrikt: uppsamlingAndrade
});

const utgaende = targetSessions.map((sid) => ({
    payload,
    _session: { type: "websocket", id: sid }
}));

return [utgaende];

// Catch-nod för pollningsflödet: ett fel här (t.ex. val.se nere en kort
// stund) ska aldrig krascha hela realtidsflödet - bara loggas. Nästa
// pollningscykel försöker automatiskt igen.
const err = msg.error || {};
node.warn("Pollningsfel (ignoreras, försöker igen nästa cykel): " + (err.message || JSON.stringify(err)));
return null;
